"""Refine source classifications and record final coverage, preserving source fingerprints."""
from fha_prepare import *
def run():
    rows=[json.loads(s) for s in (FHA/'Metadata/ASSETS.jsonl').open(encoding='utf-8')];inv=json.loads((FHA/'Metadata/SOURCE_INVENTORY.json').read_text('utf-8'));byhash={r['sha256']:r for r in rows}
    for r in inv:
        if r['detected_format']=='UNKNOWN' and r['sha256'] in byhash:
            a=byhash[r['sha256']];r['detected_format']=a['detected_format'];r['notes']+='; Refined from byte-identical preserved asset '+a['asset_id']
    jsonwrite(FHA/'Metadata/SOURCE_INVENTORY.json',inv);csvwrite(FHA/'Metadata/SOURCE_INVENTORY.csv',inv)
    summary=json.loads((FHA/'Metadata/SOURCE_SUMMARY.json').read_text('utf-8'));summary['source_format_counts']=dict(collections.Counter(r['detected_format'] for r in inv));summary['magic_hex_counts']=dict(collections.Counter(r['magic'] for r in inv));jsonwrite(FHA/'Metadata/SOURCE_SUMMARY.json',summary)
    conversion=json.loads((FHA/'Metadata/CONVERSION_SUMMARY.json').read_text('utf-8'));conversion.setdefault('initial_formats',conversion['formats']);conversion['formats']=dict(collections.Counter(r['detected_format'] for r in rows));conversion['finalized_at']=now();jsonwrite(FHA/'Metadata/CONVERSION_SUMMARY.json',conversion)
    result=dict(completed_at=now(),logical_assets=len(rows),unique_payloads=len({r['sha256'] for r in rows}),category_counts=dict(collections.Counter(r['category'] for r in rows)),format_counts=conversion['formats'],conversion_status=dict(collections.Counter(r['conversion_status'] for r in rows)),text_encodings=dict(collections.Counter(r['text_encoding'] for r in rows if r.get('text_encoding'))),audio_codecs=dict(collections.Counter(r['codec'] for r in rows if r['conversion_status']=='native_audio')),characters=dict(collections.Counter(r['character'] for r in rows)),script_extensions=dict(collections.Counter(r['extension'] for r in rows if r['category'] in {'Scripts','Scenario'})),images=sum(bool(r['thumbnail_path']) for r in rows),audio=sum(r['conversion_status']=='native_audio' for r in rows),voice=sum(r['category']=='Voice' for r in rows),bgm=sum(r['category']=='BGM' for r in rows),se=sum(r['category']=='SE' for r in rows),video=sum(r['category']=='Movies' for r in rows),scripts=sum(r['category'] in {'Scripts','Scenario'} for r in rows),text=sum(r['conversion_status'] in {'utf8_text','decoded_gettext'} for r in rows),database=sum(r['category']=='Database' for r in rows),other=sum(r['conversion_status'] in {'native_binary','preserved_metadata','indexed_binary_log','expanded_container_preserved','native_document','native_font'} for r in rows),unknown=sum(r['detected_format']=='UNKNOWN' for r in rows),converted_success=sum(r['conversion_status'] in {'converted_png','converted_browser_video','utf8_text','decoded_gettext','indexed_binary_log'} for r in rows),converted_failed=sum('failed' in r['conversion_status'] for r in rows),native_or_preserved=sum(r['conversion_status'] not in {'converted_png','converted_browser_video','utf8_text','decoded_gettext','indexed_binary_log'} for r in rows))
